// Community deck gallery. Reads gallery/index.json (generated by
// gallery/build_index.py) and renders it with search, a category filter
// and a language filter. Everything is built with textContent, so a deck
// title can never inject markup. No cookies, no tracking, no other hosts.
(function () {
  "use strict";

  var root = document.getElementById("gallery");
  if (!root) return;

  var LANG = document.documentElement.lang === "de" ? "de" : "en";
  var INDEX_URL = new URL(root.getAttribute("data-index"), location.href);
  var PATH_OK = /^decks\/[a-z0-9]+(?:-[a-z0-9]+)*\.[a-z]{2}\.json$/;

  var T = {
    en: {
      all: "All",
      categories: { languages: "Languages", knowledge: "Knowledge", mind: "Mind", tech: "Tech", life: "Life" },
      locales: { en: "English", de: "Deutsch" },
      cards: function (n) { return n === 1 ? "1 card" : n + " cards"; },
      open: "Open in Ma",
      download: "JSON",
      preview: "Preview",
      hide: "Hide preview",
      more: function (n) { return "and " + n + " more"; },
      loading: "Loading decks...",
      failed: "The deck list could not be loaded. Check your connection and try again.",
      retry: "Try again",
      previewFailed: "This deck could not be loaded.",
      none: "No deck matches. Try another word or category.",
      count: function (n) { return n === 1 ? "1 deck" : n + " decks"; },
      openLabel: function (t) { return "Open " + t + " in Ma"; },
      downloadLabel: function (t) { return "Download " + t + " as JSON"; }
    },
    de: {
      all: "Alle",
      categories: { languages: "Sprachen", knowledge: "Wissen", mind: "Geist", tech: "Technik", life: "Leben" },
      locales: { en: "English", de: "Deutsch" },
      cards: function (n) { return n === 1 ? "1 Karte" : n + " Karten"; },
      open: "In Ma öffnen",
      download: "JSON",
      preview: "Vorschau",
      hide: "Vorschau schließen",
      more: function (n) { return "und " + n + " weitere"; },
      loading: "Themen werden geladen...",
      failed: "Die Themenliste konnte nicht geladen werden. Prüf deine Verbindung und versuch es noch einmal.",
      retry: "Noch einmal",
      previewFailed: "Dieses Thema konnte nicht geladen werden.",
      none: "Kein Thema passt. Versuch ein anderes Wort oder eine andere Kategorie.",
      count: function (n) { return n === 1 ? "1 Thema" : n + " Themen"; },
      openLabel: function (t) { return t + " in Ma öffnen"; },
      downloadLabel: function (t) { return t + " als JSON laden"; }
    }
  }[LANG];

  var ORDER = ["languages", "knowledge", "mind", "tech", "life"];

  var els = {
    search: document.getElementById("q"),
    locale: document.getElementById("locale"),
    chips: document.getElementById("chips"),
    list: document.getElementById("decks"),
    status: document.getElementById("status")
  };

  var state = { decks: [], q: "", cat: "", loc: LANG };
  var deckCache = {};

  // Filters live in the query string, so a filtered view can be shared.
  (function readQuery() {
    var p = new URLSearchParams(location.search);
    state.q = p.get("q") || "";
    state.cat = ORDER.indexOf(p.get("cat")) >= 0 ? p.get("cat") : "";
    var loc = p.get("lang");
    if (loc === "all" || loc === "en" || loc === "de") state.loc = loc;
  })();
  els.search.value = state.q;
  els.locale.value = state.loc;

  function writeQuery() {
    var p = new URLSearchParams();
    if (state.q) p.set("q", state.q);
    if (state.cat) p.set("cat", state.cat);
    if (state.loc !== LANG) p.set("lang", state.loc);
    var qs = p.toString();
    try { history.replaceState(null, "", location.pathname + (qs ? "?" + qs : "") + location.hash); } catch (e) {}
  }

  function el(tag, cls, text) {
    var node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text != null) node.textContent = text;
    return node;
  }

  function deckURL(entry) { return new URL(entry.path, INDEX_URL).href; }

  function normalize(s) {
    return String(s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  }

  function matchesText(d) {
    if (!state.q) return true;
    var hay = normalize([d.title, d.subtitle, d.id, T.categories[d.category] || d.category].join(" "));
    return normalize(state.q).split(/\s+/).every(function (w) { return !w || hay.indexOf(w) >= 0; });
  }

  function matchesLocale(d) { return state.loc === "all" || d.locale === state.loc; }

  function renderChips() {
    var pool = state.decks.filter(function (d) { return matchesText(d) && matchesLocale(d); });
    var counts = {};
    pool.forEach(function (d) { counts[d.category] = (counts[d.category] || 0) + 1; });
    els.chips.textContent = "";
    var cats = [""].concat(ORDER.filter(function (c) {
      return state.decks.some(function (d) { return d.category === c; });
    }));
    cats.forEach(function (c) {
      var b = el("button", "chip");
      b.type = "button";
      b.setAttribute("aria-pressed", String(state.cat === c));
      b.appendChild(document.createTextNode(c ? (T.categories[c] || c) : T.all));
      b.appendChild(el("span", "n", String(c ? (counts[c] || 0) : pool.length)));
      b.addEventListener("click", function () {
        state.cat = c;
        update();
      });
      els.chips.appendChild(b);
    });
  }

  function renderPreview(box, entry) {
    box.textContent = "";
    box.appendChild(el("p", "more", T.loading));
    var url = deckURL(entry);
    var load = deckCache[url] || (deckCache[url] = fetch(url, { cache: "no-cache" }).then(function (r) {
      if (!r.ok) throw new Error(r.status);
      return r.json();
    }));
    load.then(function (deck) {
      box.textContent = "";
      var cards = Array.isArray(deck.cards) ? deck.cards : [];
      cards.slice(0, 5).forEach(function (c) {
        var item = el("div");
        item.appendChild(el("div", "q", c.prompt));
        item.appendChild(el("div", "a", c.answer));
        if (c.note) item.appendChild(el("div", "n", c.note));
        box.appendChild(item);
      });
      if (cards.length > 5) box.appendChild(el("p", "more", T.more(cards.length - 5)));
    }).catch(function () {
      delete deckCache[url];
      box.textContent = "";
      box.appendChild(el("p", "more", T.previewFailed));
    });
  }

  function card(entry) {
    var art = el("article", "card deck");
    art.id = "deck-" + entry.id + "-" + entry.locale;

    var top = el("div", "deck-top");
    var seal = el("div", "seal", entry.symbol || "");
    seal.setAttribute("aria-hidden", "true");
    top.appendChild(seal);
    var head = el("div");
    head.appendChild(el("h3", null, entry.title));
    if (entry.subtitle) head.appendChild(el("p", "sub", entry.subtitle));
    top.appendChild(head);
    art.appendChild(top);

    var facts = el("div", "facts");
    facts.appendChild(el("span", null, T.cards(entry.cardCount)));
    facts.appendChild(el("span", null, T.locales[entry.locale] || entry.locale));
    facts.appendChild(el("span", null, T.categories[entry.category] || entry.category));
    art.appendChild(facts);

    var url = deckURL(entry);
    var actions = el("div", "actions");

    var open = el("a", "btn btn-primary btn-sm", T.open);
    open.href = "ma://import?url=" + encodeURIComponent(url);
    open.setAttribute("aria-label", T.openLabel(entry.title));
    actions.appendChild(open);

    var dl = el("a", "btn btn-quiet btn-sm", T.download);
    dl.href = url;
    dl.setAttribute("download", entry.id + "." + entry.locale + ".json");
    dl.setAttribute("aria-label", T.downloadLabel(entry.title));
    actions.appendChild(dl);

    var pv = el("button", "btn btn-quiet btn-sm", T.preview);
    pv.type = "button";
    pv.setAttribute("aria-expanded", "false");
    var box = el("div", "preview");
    box.hidden = true;
    box.id = art.id + "-preview";
    pv.setAttribute("aria-controls", box.id);
    pv.addEventListener("click", function () {
      var opening = box.hidden;
      box.hidden = !opening;
      pv.textContent = opening ? T.hide : T.preview;
      pv.setAttribute("aria-expanded", String(opening));
      if (opening && !box.childNodes.length) renderPreview(box, entry);
    });
    actions.appendChild(pv);

    art.appendChild(actions);
    art.appendChild(box);
    return art;
  }

  function renderList() {
    var shown = state.decks.filter(function (d) {
      return matchesText(d) && matchesLocale(d) && (!state.cat || d.category === state.cat);
    });
    els.list.textContent = "";
    if (!shown.length) {
      var empty = el("div", "empty");
      var img = el("img");
      img.src = root.getAttribute("data-empty-art");
      img.alt = "";
      empty.appendChild(img);
      empty.appendChild(el("p", null, T.none));
      els.list.appendChild(empty);
    } else {
      shown.forEach(function (d) { els.list.appendChild(card(d)); });
    }
    els.status.textContent = T.count(shown.length);
  }

  function update() {
    writeQuery();
    renderChips();
    renderList();
  }

  function sortDecks(list) {
    return list.slice().sort(function (a, b) {
      var ca = ORDER.indexOf(a.category), cb = ORDER.indexOf(b.category);
      if (ca !== cb) return (ca < 0 ? 99 : ca) - (cb < 0 ? 99 : cb);
      return String(a.title).localeCompare(String(b.title), LANG);
    });
  }

  function load() {
    els.list.textContent = "";
    els.list.appendChild(el("p", "empty", T.loading));
    fetch(INDEX_URL.href, { cache: "no-cache" })
      .then(function (r) {
        if (!r.ok) throw new Error(r.status);
        return r.json();
      })
      .then(function (data) {
        var list = Array.isArray(data) ? data : (data && data.decks) || [];
        state.decks = sortDecks(list.filter(function (d) {
          return d && d.id && d.title && typeof d.path === "string" && PATH_OK.test(d.path);
        }));
        update();
      })
      .catch(function () {
        els.list.textContent = "";
        var box = el("div", "empty");
        box.appendChild(el("p", null, T.failed));
        var retry = el("button", "btn btn-quiet btn-sm mt-lg", T.retry);
        retry.type = "button";
        retry.addEventListener("click", load);
        box.appendChild(retry);
        els.list.appendChild(box);
        els.status.textContent = "";
      });
  }

  var timer;
  els.search.addEventListener("input", function () {
    clearTimeout(timer);
    timer = setTimeout(function () {
      state.q = els.search.value.trim();
      update();
    }, 120);
  });
  els.locale.addEventListener("change", function () {
    state.loc = els.locale.value;
    update();
  });

  load();
})();
